    SELECT SEQPAYMENT.NEXTVAL FROM DUAL


INSERT INTO PAYMENT (
    PAYMENTIDX, IMPUID, MERCHANTUID, CHARGEAMOUNT, 
    PAYMETHOD, PAYSTATUS, USERIDX
) VALUES (
    #{paymentIdx}, #{impUid}, #{merchantUid}, #{chargeAmount}, 
    #{payMethod}, #{payStatus}, #{userIdx}
)

INSERT INTO POINTHISTORY (
    HISTORYIDX, PAYMENTIDX, AMOUNT, HISTORYTYPE, USERIDX, TOTALPOINT
) VALUES (
     SEQPOINTHISTORY.NEXTVAL, #{paymentIdx}, #{amount}, #{historyType}, #{userIdx}, #{totalPoint} 
)

