SELECT NVL(MAX(BATONPOINT), 0) 
FROM USERS 
WHERE USERIDX = #{userIdx}

mapper.update:
UPDATE USERS 
SET BATONPOINT = NVL(BATONPOINT, 0) + #{point} 
WHERE USERIDX = #{userIdx}
